@Test
public void testForkMethods() {
    ForkOperator<String, String> dummyForkOperator = new IdentityForkOperator<String, String>();
    WorkUnitState workUnitState = new WorkUnitState();
    workUnitState.setProp(ConfigurationKeys.FORK_BRANCHES_KEY, 2);
    List<Boolean> schemas = dummyForkOperator.forkSchema(workUnitState, "");
    Assert.assertEquals(schemas, Arrays.asList(true, true));
    List<Boolean> records = dummyForkOperator.forkDataRecord(workUnitState, "");
    Assert.assertEquals(records, Arrays.asList(true, true));
    Assert.assertEquals(dummyForkOperator.getBranches(workUnitState), 2);
    workUnitState.setProp(ConfigurationKeys.FORK_BRANCHES_KEY, 0);
    schemas = dummyForkOperator.forkSchema(workUnitState, "");
    Assert.assertTrue(schemas.isEmpty());
    records = dummyForkOperator.forkDataRecord(workUnitState, "");
    Assert.assertTrue(records.isEmpty());
    Assert.assertEquals(dummyForkOperator.getBranches(workUnitState), 0);
}

@Test
public void testConfigureFromTypesafe() {
    {
        Config cfg = ConfigFactory.empty().withValue(DefaultHttpClientConfigurator.PROXY_HOSTPORT_KEY, ConfigValueFactory.fromAnyRef("localhost:12345"));
        Optional<HttpHost> proxyHost = DefaultHttpClientConfigurator.getProxyAddr(cfg);
        Assert.assertTrue(proxyHost.isPresent());
        Assert.assertEquals(proxyHost.get(), new HttpHost("localhost", 12345));
    }
    {
        Config cfg = ConfigFactory.empty().withValue(DefaultHttpClientConfigurator.PROXY_HOSTPORT_KEY, ConfigValueFactory.fromAnyRef("localhost"));
        Optional<HttpHost> proxyHost = DefaultHttpClientConfigurator.getProxyAddr(cfg);
        Assert.assertTrue(proxyHost.isPresent());
        Assert.assertEquals(proxyHost.get(), new HttpHost("localhost", DefaultHttpClientConfigurator.DEFAULT_HTTP_PROXY_PORT));
    }
    {
        Config cfg = ConfigFactory.empty().withValue(DefaultHttpClientConfigurator.PROXY_URL_KEY, ConfigValueFactory.fromAnyRef("host123"));
        Optional<HttpHost> proxyHost = DefaultHttpClientConfigurator.getProxyAddr(cfg);
        Assert.assertTrue(proxyHost.isPresent());
        Assert.assertEquals(proxyHost.get(), new HttpHost("host123", DefaultHttpClientConfigurator.DEFAULT_HTTP_PROXY_PORT));
    }
    {
        Config cfg = ConfigFactory.empty().withValue(DefaultHttpClientConfigurator.PROXY_URL_KEY, ConfigValueFactory.fromAnyRef("host123")).withValue(DefaultHttpClientConfigurator.PROXY_PORT_KEY, ConfigValueFactory.fromAnyRef(54321));
        Optional<HttpHost> proxyHost = DefaultHttpClientConfigurator.getProxyAddr(cfg);
        Assert.assertTrue(proxyHost.isPresent());
        Assert.assertEquals(proxyHost.get(), new HttpHost("host123", 54321));
    }
    {
        Config cfg = ConfigFactory.empty();
        Optional<HttpHost> proxyHost = DefaultHttpClientConfigurator.getProxyAddr(cfg);
        Assert.assertFalse(proxyHost.isPresent());
    }
}

