@Test
public void testMultipleClose() throws IOException {
    Properties properties = new Properties();
    properties.load(new FileReader("gobblin-core/src/test/resources/writer/hive_writer.properties"));
    properties.setProperty("writer.staging.dir", new Path(tmpDir.getAbsolutePath(), "output-staging").toString());
    properties.setProperty("writer.output.dir", new Path(tmpDir.getAbsolutePath(), "output").toString());
    properties.setProperty("writer.file.path", ".");
    SourceState sourceState = new SourceState(new State(properties), ImmutableList.<WorkUnitState>of());
    DataWriter writer = new HiveWritableHdfsDataWriterBuilder<>().withBranches(1).withWriterId("0").writeTo(Destination.of(Destination.DestinationType.HDFS, sourceState)).writeInFormat(WriterOutputFormat.ORC).build();
    writer.close();
    // check for file existence
    Assert.assertTrue(this.fs.exists(new Path(new Path(tmpDir.getAbsolutePath(), "output-staging"), "writer-output.orc")), "staging file not found");
    // closed again is okay
    writer.close();
    // commit after close is okay
    writer.commit();
    Assert.assertTrue(this.fs.exists(new Path(new Path(tmpDir.getAbsolutePath(), "output"), "writer-output.orc")), "output file not found");
}

