@Test
public void testDerivePartitionPattern() {
    String slashTimeFormat = "yyyy/MM/dd";
    String dashTimeFormat = "yyyy-MM-dd";
    // 2019/12/1 - 2019/12/3
    LocalDateTime localTime = LocalDateTime.of(2019, 12, 3, 0, 0);
    ZonedDateTime end = ZonedDateTime.of(localTime, zone);
    ZonedDateTime start = end.withDayOfMonth(1);
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, slashTimeFormat), "{2019}/{12}/*");
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, dashTimeFormat), "{2019}-{12}*");
    // 2019/11/30 - 2019/12/3
    start = end.withMonth(11).withDayOfMonth(30);
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, slashTimeFormat), "{2019}/{11,12}/*");
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, dashTimeFormat), "{2019}-{11,12}*");
    // 2018/12/1 - 2019/12/3
    start = end.withYear(2018).withMonth(12).withDayOfMonth(1);
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, slashTimeFormat), "{2018,2019}/*/*");
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, dashTimeFormat), "{2018,2019}-*");
    // 2018/11/30 - 2019/12/3
    start = end.withYear(2018).withMonth(11).withDayOfMonth(30);
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, slashTimeFormat), "{2018,2019}/*/*");
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, dashTimeFormat), "{2018,2019}-*");
    // 2018/11/30 - 2019/01/3
    end = end.withMonth(1);
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, slashTimeFormat), "{2018,2019}/{11,12,01}/*");
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, dashTimeFormat), "{2018,2019}-{11,12,01}*");
    // Test hourly
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, "yyyy/MM/dd/HH"), "{2018,2019}/{11,12,01}/*/*");
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, "yyyy-MM-dd-HH"), "{2018,2019}-{11,12,01}*");
    // 2019/1/1 - 2019/1/3
    start = start.withYear(2019).withMonth(1).withDayOfMonth(1);
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, slashTimeFormat), "{2019}/{01}/*");
    Assert.assertEquals(TimePartitionGlobFinder.derivePartitionPattern(start, end, dashTimeFormat), "{2019}-{01}*");
}

