@Test
public void testCleanJobStateStore() throws IOException {
    JobState jobState = new JobState(TEST_JOB_NAME1, getJobId(TEST_JOB_ID, 1));
    jobState.setId(getJobId(TEST_JOB_ID, 1));
    jobState.setProp("foo", "bar");
    jobState.setState(JobState.RunningState.COMMITTED);
    jobState.setStartTime(this.startTime);
    jobState.setEndTime(this.startTime + 1000);
    jobState.setDuration(1000);
    for (int i = 0; i < 3; i++) {
        TaskState taskState = new TaskState();
        taskState.setJobId(getJobId(TEST_JOB_ID, 1));
        taskState.setTaskId(TEST_TASK_ID_PREFIX + i);
        taskState.setId(TEST_TASK_ID_PREFIX + i);
        taskState.setWorkingState(WorkUnitState.WorkingState.COMMITTED);
        jobState.addTaskState(taskState);
    }
    // set old time to test that this state is deleted
    this.dbJobStateStore.setTestTimestamp(System.currentTimeMillis() / 1000 - (60 * 20));
    this.dbJobStateStore.put(TEST_JOB_NAME1, MysqlDatasetStateStore.CURRENT_DATASET_STATE_FILE_SUFFIX + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX, jobState);
    jobState.setJobName(TEST_JOB_NAME2);
    jobState.setJobId(getJobId(TEST_JOB_ID, 2));
    jobState.setId(getJobId(TEST_JOB_ID, 2));
    // set current time to test that the state is not deleted
    this.dbJobStateStore.setTestTimestamp(0);
    this.dbJobStateStore.put(TEST_JOB_NAME2, MysqlDatasetStateStore.CURRENT_DATASET_STATE_FILE_SUFFIX + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX, jobState);
    TimeBasedDatasetStoreDatasetFinder datasetFinder = new TimeBasedDatasetStoreDatasetFinder(FileSystem.get(new Configuration()), ConfigUtils.configToProperties(config));
    List<DatasetStoreDataset> datasets = datasetFinder.findDatasets();
    Assert.assertTrue(this.dbJobStateStore.exists(TEST_JOB_NAME1, MysqlDatasetStateStore.CURRENT_DATASET_STATE_FILE_SUFFIX + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbJobStateStore.exists(TEST_JOB_NAME2, MysqlDatasetStateStore.CURRENT_DATASET_STATE_FILE_SUFFIX + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    for (DatasetStoreDataset dataset : datasets) {
        ((CleanableDataset) dataset).clean();
    }
    Assert.assertFalse(this.dbJobStateStore.exists(TEST_JOB_NAME1, MysqlDatasetStateStore.CURRENT_DATASET_STATE_FILE_SUFFIX + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    // state with recent timestamp is not deleted
    Assert.assertTrue(this.dbJobStateStore.exists(TEST_JOB_NAME2, MysqlDatasetStateStore.CURRENT_DATASET_STATE_FILE_SUFFIX + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
}

