public void testCleanDatasetStateStore() throws IOException {
    JobState.DatasetState datasetState = new JobState.DatasetState(TEST_JOB_NAME1, getJobId(TEST_JOB_ID, 1));
    datasetState.setDatasetUrn(TEST_DATASET_URN1);
