    datasetState.setDuration(1000);
    for (int i = 0; i < 3; i++) {
        TaskState taskState = new TaskState();
        taskState.setJobId(getJobId(TEST_JOB_ID, 1));
        taskState.setTaskId(TEST_TASK_ID_PREFIX + i);
        taskState.setId(TEST_TASK_ID_PREFIX + i);
        taskState.setWorkingState(WorkUnitState.WorkingState.COMMITTED);
        datasetState.addTaskState(taskState);
    }
    // set old time to test that this state is deleted
    ((MysqlDatasetStateStore) this.dbDatasetStateStore).setTestTimestamp(this.startTime / 1000 + 2 - (60 * 20));
    datasetState.setJobId(getJobId(TEST_JOB_ID, 1));
    this.dbDatasetStateStore.persistDatasetState(TEST_DATASET_URN1, datasetState);
    ((MysqlDatasetStateStore) this.dbDatasetStateStore).setTestTimestamp(this.startTime / 1000 + 4 - (60 * 20));
    datasetState.setJobId(getJobId(TEST_JOB_ID, 2));
    this.dbDatasetStateStore.persistDatasetState(TEST_DATASET_URN1, datasetState);
    ((MysqlDatasetStateStore) this.dbDatasetStateStore).setTestTimestamp(this.startTime / 1000 + 6 - (60 * 20));
    datasetState.setJobId(getJobId(TEST_JOB_ID, 3));
    this.dbDatasetStateStore.persistDatasetState(TEST_DATASET_URN1, datasetState);
    datasetState.setJobId(getJobId(TEST_JOB_ID, 1));
    // persist a second dataset state to test that retrieval of multiple dataset states works
    datasetState.setDatasetUrn(TEST_DATASET_URN2);
    datasetState.setId(TEST_DATASET_URN2);
    datasetState.setDuration(2000);
    // set current time to test that the state is not deleted
    ((MysqlDatasetStateStore) this.dbDatasetStateStore).setTestTimestamp(0);
    this.dbDatasetStateStore.persistDatasetState(TEST_DATASET_URN2, datasetState);
    datasetState.setJobName(TEST_JOB_NAME2);
    this.dbDatasetStateStore.persistDatasetState(TEST_DATASET_URN2, datasetState);
    Config cleanerConfig = config.withValue("gobblin.retention.selection.policy.class", ConfigValueFactory.fromAnyRef("org.apache.gobblin.data.management.policy.CombineSelectionPolicy")).withValue("gobblin.retention.selection.combine.operation", ConfigValueFactory.fromAnyRef("intersect")).withValue("gobblin.retention.selection.combine.policy.classes", ConfigValueFactory.fromAnyRef("org.apache.gobblin.data.management.policy.SelectBeforeTimeBasedPolicy,org.apache.gobblin.data.management.policy.NewestKSelectionPolicy")).withValue("gobblin.retention.selection.timeBased.lookbackTime", ConfigValueFactory.fromAnyRef("10m")).withValue("gobblin.retention.selection.newestK.versionsNotSelected", ConfigValueFactory.fromAnyRef("2"));
    TimeBasedDatasetStoreDatasetFinder datasetFinder = new TimeBasedDatasetStoreDatasetFinder(FileSystem.get(new Configuration()), ConfigUtils.configToProperties(cleanerConfig));
    List<DatasetStoreDataset> datasets = datasetFinder.findDatasets();
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME1, TEST_DATASET_URN1 + "-" + MysqlDatasetStateStore.CURRENT_DATASET_STATE_FILE_SUFFIX + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME1, TEST_DATASET_URN1 + "-" + getJobId(TEST_JOB_ID, 1) + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME1, TEST_DATASET_URN1 + "-" + getJobId(TEST_JOB_ID, 2) + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME1, TEST_DATASET_URN1 + "-" + getJobId(TEST_JOB_ID, 3) + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME1, TEST_DATASET_URN2 + "-" + MysqlDatasetStateStore.CURRENT_DATASET_STATE_FILE_SUFFIX + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME1, TEST_DATASET_URN2 + "-" + getJobId(TEST_JOB_ID, 1) + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME2, TEST_DATASET_URN2 + "-" + MysqlDatasetStateStore.CURRENT_DATASET_STATE_FILE_SUFFIX + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME2, TEST_DATASET_URN2 + "-" + getJobId(TEST_JOB_ID, 1) + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    for (DatasetStoreDataset dataset : datasets) {
        ((CleanableDataset) dataset).clean();
    }
    // the most recent two entries (current and job id 3) should be retained
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME1, TEST_DATASET_URN1 + "-" + MysqlDatasetStateStore.CURRENT_DATASET_STATE_FILE_SUFFIX + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME1, TEST_DATASET_URN1 + "-" + getJobId(TEST_JOB_ID, 3) + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertFalse(this.dbDatasetStateStore.exists(TEST_JOB_NAME1, TEST_DATASET_URN1 + "-" + getJobId(TEST_JOB_ID, 1) + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertFalse(this.dbDatasetStateStore.exists(TEST_JOB_NAME1, TEST_DATASET_URN1 + "-" + getJobId(TEST_JOB_ID, 2) + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME1, TEST_DATASET_URN2 + "-" + MysqlDatasetStateStore.CURRENT_DATASET_STATE_FILE_SUFFIX + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME1, TEST_DATASET_URN2 + "-" + getJobId(TEST_JOB_ID, 1) + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME2, TEST_DATASET_URN2 + "-" + MysqlDatasetStateStore.CURRENT_DATASET_STATE_FILE_SUFFIX + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
    Assert.assertTrue(this.dbDatasetStateStore.exists(TEST_JOB_NAME2, TEST_DATASET_URN2 + "-" + getJobId(TEST_JOB_ID, 1) + MysqlDatasetStateStore.DATASET_STATE_STORE_TABLE_SUFFIX));
}

