@Test
public void testKeepLast2YearsOfDailyPartitions() throws Exception {
    //61 days
    insertDailyPartition(new Path("/data/tracking/MetricEvent/daily/2015/11/25"));
    // 55 days
    insertDailyPartition(new Path("/data/tracking/MetricEvent/daily/2015/12/01"));
    // 430 days
    insertDailyPartition(new Path("/data/tracking/MetricEvent/daily/2014/11/21"));
    // 733 days (more than 2 years)
    insertDailyPartition(new Path("/data/tracking/MetricEvent/daily/2014/01/22"));
    // 1095 days (more than 2 years)
    insertDailyPartition(new Path("/data/tracking/MetricEvent/daily/2013/01/25"));
    // Use the current timestamp for consistent test results.
    Timestamp currentTimestamp = new Timestamp(DateTimeFormat.forPattern(DAILY_PARTITION_PATTERN).parseDateTime("2016/01/25").getMillis());
    PreparedStatement statement = connection.prepareStatement("SELECT path FROM Daily_Partitions WHERE TIMESTAMP_DIFF(?, ts, 'Days') > ?");
    statement.setTimestamp(1, currentTimestamp);
    statement.setLong(2, TWO_YEARS_IN_DAYS);
    ResultSet rs = statement.executeQuery();
    // Daily partitions to be cleaned
    rs.next();
    Assert.assertEquals(rs.getString(1), "/data/tracking/MetricEvent/daily/2014/01/22");
    rs.next();
    Assert.assertEquals(rs.getString(1), "/data/tracking/MetricEvent/daily/2013/01/25");
}

@Test
public void testISORetentionDuration() throws Exception {
    DateTimeUtils.setCurrentMillisFixed(new DateTime(2016, 2, 11, 10, 0, 0, 0).getMillis());
    try {
        // 20 Days
        verify("P20D", ImmutableList.of(WithDate(new DateTime(2016, 1, 5, 10, 0, 0, 0)), WithDate(new DateTime(2016, 1, 6, 10, 0, 0, 0))), ImmutableList.of(WithDate(new DateTime(2016, 2, 10, 10, 0, 0, 0)), WithDate(new DateTime(2016, 2, 11, 10, 0, 0, 0))));
        // 2 Months
        verify("P2M", ImmutableList.of(WithDate(new DateTime(2015, 12, 5, 10, 0, 0, 0)), WithDate(new DateTime(2015, 11, 5, 10, 0, 0, 0))), ImmutableList.of(WithDate(new DateTime(2016, 2, 10, 10, 0, 0, 0)), WithDate(new DateTime(2016, 1, 10, 10, 0, 0, 0))));
        // 2 Years
        verify("P2Y", ImmutableList.of(WithDate(new DateTime(2014, 1, 5, 10, 0, 0, 0)), WithDate(new DateTime(2013, 1, 5, 10, 0, 0, 0))), ImmutableList.of(WithDate(new DateTime(2016, 2, 10, 10, 0, 0, 0)), WithDate(new DateTime(2015, 2, 10, 10, 0, 0, 0))));
        // 20 Hours
        verify("PT20H", ImmutableList.of(WithDate(new DateTime(2016, 2, 10, 11, 0, 0, 0)), WithDate(new DateTime(2016, 2, 9, 11, 0, 0, 0))), ImmutableList.of(WithDate(new DateTime(2016, 2, 11, 8, 0, 0, 0)), WithDate(new DateTime(2016, 2, 11, 9, 0, 0, 0))));
    } finally {
        // Restore time
        DateTimeUtils.setCurrentMillisSystem();
    }
}

