public void testNoMoreThanOneRequestAtATime() throws Exception {
    Queue<RequestAndCallback> queue = Queues.newArrayDeque();
    BatchedPermitsRequester container = BatchedPermitsRequester.builder().resourceId("resource").requestorIdentifier("requestor").requestSender(new TestRequestSender(queue, false)).build();
