        limiterServer.getSync(new ComplexResourceKey<>(res1request, new EmptyRecord())).getPermits();
        Assert.fail();
    } catch (RestLiServiceException exc) {
        Assert.assertEquals(exc.getStatus(), HttpStatus.S_403_FORBIDDEN);
