@Test
public void testContains() throws IOException {
    //Ensure descriptor2's path is matched by the regular expression in descriptor1's path
    Config config1 = ConfigFactory.empty().withValue(DatasetDescriptorConfigKeys.PATH_KEY, ConfigValueFactory.fromAnyRef("/a/b/c/*")).withValue(DatasetDescriptorConfigKeys.PLATFORM_KEY, ConfigValueFactory.fromAnyRef("hdfs"));
    FSDatasetDescriptor descriptor1 = new FSDatasetDescriptor(config1);
    Config config2 = ConfigFactory.empty().withValue(DatasetDescriptorConfigKeys.PATH_KEY, ConfigValueFactory.fromAnyRef("/a/b/c/d")).withValue(DatasetDescriptorConfigKeys.PLATFORM_KEY, ConfigValueFactory.fromAnyRef("hdfs")).withValue(DatasetDescriptorConfigKeys.FORMAT_KEY, ConfigValueFactory.fromAnyRef("avro")).withValue(DatasetDescriptorConfigKeys.CODEC_KEY, ConfigValueFactory.fromAnyRef("gzip"));
    FSDatasetDescriptor descriptor2 = new FSDatasetDescriptor(config2);
    Assert.assertTrue(descriptor1.contains(descriptor2));
    //Add encryption config
    Config encConfig = ConfigFactory.empty().withValue(DatasetDescriptorConfigKeys.ENCRYPTION_LEVEL_KEY, ConfigValueFactory.fromAnyRef("file")).withValue(DatasetDescriptorConfigKeys.ENCRYPTION_ALGORITHM_KEY, ConfigValueFactory.fromAnyRef("aes_rotating")).atPath(DatasetDescriptorConfigKeys.ENCYPTION_PREFIX);
    Config config3 = config2.withFallback(encConfig);
    FSDatasetDescriptor descriptor3 = new FSDatasetDescriptor(config3);
    Assert.assertTrue(descriptor2.contains(descriptor3));
    Assert.assertTrue(descriptor1.contains(descriptor3));
    //Add partition config
    Config partitionConfig = ConfigFactory.empty().withValue(DatasetDescriptorConfigKeys.PARTITION_TYPE_KEY, ConfigValueFactory.fromAnyRef("datetime")).withValue(DatasetDescriptorConfigKeys.PARTITION_PATTERN_KEY, ConfigValueFactory.fromAnyRef("yyyy/MM/dd")).atPath(DatasetDescriptorConfigKeys.PARTITION_PREFIX);
    Config config4 = config3.withFallback(partitionConfig);
    FSDatasetDescriptor descriptor4 = new FSDatasetDescriptor(config4);
    Assert.assertTrue(descriptor3.contains(descriptor4));
    Assert.assertTrue(descriptor2.contains(descriptor4));
    Assert.assertTrue(descriptor1.contains(descriptor4));
    //Add compaction/retention config
    Config miscConfig = ConfigFactory.empty().withValue(DatasetDescriptorConfigKeys.IS_COMPACTED_AND_DEDUPED_KEY, ConfigValueFactory.fromAnyRef("true")).withValue(DatasetDescriptorConfigKeys.IS_RETENTION_APPLIED_KEY, ConfigValueFactory.fromAnyRef("true"));
    Config config5 = config4.withFallback(miscConfig);
    FSDatasetDescriptor descriptor5 = new FSDatasetDescriptor(config5);
    Assert.assertFalse(descriptor4.contains(descriptor5));
    Assert.assertFalse(descriptor3.contains(descriptor5));
    Assert.assertFalse(descriptor2.contains(descriptor5));
    Assert.assertFalse(descriptor1.contains(descriptor5));
    // Test subpaths
    Config subPathConfig = ConfigFactory.empty().withValue(DatasetDescriptorConfigKeys.PATH_KEY, ConfigValueFactory.fromAnyRef("/a/b/c")).withValue(DatasetDescriptorConfigKeys.SUBPATHS_KEY, ConfigValueFactory.fromAnyRef("{e,f,g}")).withValue(DatasetDescriptorConfigKeys.PLATFORM_KEY, ConfigValueFactory.fromAnyRef("hdfs"));
    FSDatasetDescriptor descriptor6 = new FSDatasetDescriptor(subPathConfig);
    Assert.assertTrue(descriptor1.contains(descriptor6));
    Assert.assertFalse(descriptor2.contains(descriptor6));
}

@Test
public void testEquals() throws IOException {
    Config config1 = ConfigFactory.empty().withValue(DatasetDescriptorConfigKeys.PATH_KEY, ConfigValueFactory.fromAnyRef("/a/b/c/*")).withValue(DatasetDescriptorConfigKeys.PLATFORM_KEY, ConfigValueFactory.fromAnyRef("hdfs"));
    FSDatasetDescriptor descriptor1 = new FSDatasetDescriptor(config1);
    Config config2 = ConfigFactory.empty().withValue(DatasetDescriptorConfigKeys.PATH_KEY, ConfigValueFactory.fromAnyRef("/a/b/c/*")).withValue(DatasetDescriptorConfigKeys.PLATFORM_KEY, ConfigValueFactory.fromAnyRef("hdfs"));
    FSDatasetDescriptor descriptor2 = new FSDatasetDescriptor(config2);
    Assert.assertTrue(descriptor1.equals(descriptor2));
    Assert.assertTrue(descriptor2.equals(descriptor1));
    Assert.assertEquals(descriptor1.hashCode(), descriptor2.hashCode());
    Config config3 = ConfigFactory.empty().withValue(DatasetDescriptorConfigKeys.PATH_KEY, ConfigValueFactory.fromAnyRef("/a/b/c/*")).withValue(DatasetDescriptorConfigKeys.PLATFORM_KEY, ConfigValueFactory.fromAnyRef("hdfs")).withValue(DatasetDescriptorConfigKeys.FORMAT_KEY, ConfigValueFactory.fromAnyRef("any")).withValue(DatasetDescriptorConfigKeys.IS_RETENTION_APPLIED_KEY, ConfigValueFactory.fromAnyRef("false"));
    FSDatasetDescriptor descriptor3 = new FSDatasetDescriptor(config3);
    Assert.assertTrue(descriptor1.equals(descriptor3));
    Assert.assertEquals(descriptor1.hashCode(), descriptor3.hashCode());
    //Ensure switching booleans between 2 boolean member variables does not produce the same hashcode.
    Config config4 = ConfigFactory.empty().withValue(DatasetDescriptorConfigKeys.PATH_KEY, ConfigValueFactory.fromAnyRef("/a/b/c/*")).withValue(DatasetDescriptorConfigKeys.PLATFORM_KEY, ConfigValueFactory.fromAnyRef("hdfs")).withValue(DatasetDescriptorConfigKeys.FORMAT_KEY, ConfigValueFactory.fromAnyRef("any")).withValue(DatasetDescriptorConfigKeys.IS_RETENTION_APPLIED_KEY, ConfigValueFactory.fromAnyRef("false")).withValue(DatasetDescriptorConfigKeys.IS_COMPACTED_KEY, ConfigValueFactory.fromAnyRef("true"));
    FSDatasetDescriptor descriptor4 = new FSDatasetDescriptor(config4);
    Config config5 = ConfigFactory.empty().withValue(DatasetDescriptorConfigKeys.PATH_KEY, ConfigValueFactory.fromAnyRef("/a/b/c/*")).withValue(DatasetDescriptorConfigKeys.PLATFORM_KEY, ConfigValueFactory.fromAnyRef("hdfs")).withValue(DatasetDescriptorConfigKeys.FORMAT_KEY, ConfigValueFactory.fromAnyRef("any")).withValue(DatasetDescriptorConfigKeys.IS_RETENTION_APPLIED_KEY, ConfigValueFactory.fromAnyRef("true")).withValue(DatasetDescriptorConfigKeys.IS_COMPACTED_KEY, ConfigValueFactory.fromAnyRef("false"));
    FSDatasetDescriptor descriptor5 = new FSDatasetDescriptor(config5);
    Assert.assertFalse(descriptor4.equals(descriptor5));
    Assert.assertNotEquals(descriptor4.hashCode(), descriptor5.hashCode());
}

