    List<String> dirs = Lists.newArrayList("inbound", "outbound");
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2; j++) {
            FSDatasetDescriptor datasetDescriptor;
            if (j == 0) {
                datasetDescriptor = (FSDatasetDescriptor) inputOutputDescriptors.get(i).getLeft();
