@Test
public void testMovePath() throws IOException, URISyntaxException {
    String expected = "test";
    ByteArrayOutputStream actual = new ByteArrayOutputStream();
    Path src = new Path("/src/file.txt");
    Path dst = new Path("/dst/file.txt");
